const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfo(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo(resolve, reject);
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const city = ee.Geometry.Point([-71.23, -29.90]); // La Serena, inland to avoid ocean-only pixels
    const region = city.buffer(5000); // 5 km
    const start = '2022-07-01';
    const end = '2022-08-01';
    const threshMM = 60.0;

    console.log('Target: La Serena, Chile (5 km buffer)');
    console.log('Period: 2022-07');

    // Helper to compute monthly total (time-sum) then spatial mean and valid pixel count.
    async function meanAndCount(img, band, geom, scale) {
      const stats = await getInfo(
        img.reduceRegion({
          reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
          geometry: geom,
          scale: scale,
          maxPixels: 1e9
        })
      );
      const mean = stats ? stats[band + '_mean'] : null;
      const count = stats ? stats[band + '_count'] : 0;
      return {mean, count};
    }

    // 2. Primary dataset: CHIRPS Daily
    let answerVal = null;
    let usedDataset = null;

    const chirpsCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, end)
      .select('precipitation');

    const chirpsCount = await getInfo(chirpsCol.size());
    console.log(`CHIRPS Daily Images: ${chirpsCount}`);

    if (chirpsCount === 0) {
      // Fallback to ERA5-Land Hourly
      console.log('CHIRPS empty. Fallback -> ERA5-Land');
    } else {
      const chirpsSum = chirpsCol.sum(); // mm over July
      const chirpsStats = await meanAndCount(chirpsSum, 'precipitation', region, 5000);
      const cMean = chirpsStats.mean;
      const cPx = chirpsStats.count;
      console.log(`CHIRPS Pixels: ${cPx}, July total (mm, area-mean): ${cMean !== null ? cMean.toFixed(1) : 'null'}`);

      if (cPx > 0 && cMean !== null && isFinite(cMean)) {
        answerVal = cMean;
        usedDataset = 'CHIRPS';
      } else {
        console.log('CHIRPS invalid/empty over region. Fallback -> ERA5-Land');
      }
    }

    // 3. Fallback dataset: ERA5-Land Hourly (sum hourly total_precipitation, convert m -> mm)
    if (answerVal === null) {
      const eraCol = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
        .filterDate(start, end)
        .select('total_precipitation');

      const eraCount = await getInfo(eraCol.size());
      console.log(`ERA5 Hourly Images: ${eraCount}`);

      if (eraCount === 0) {
        console.log('Both datasets empty for the period/location.');
        console.log('C1');
        return;
      }

      const eraSumMM = eraCol.sum().multiply(1000).rename('precipitation'); // m -> mm
      const eraStats = await meanAndCount(eraSumMM, 'precipitation', region, 9000);
      const eMean = eraStats.mean;
      const ePx = eraStats.count;
      console.log(`ERA5 Pixels: ${ePx}, July total (mm, area-mean): ${eMean !== null ? eMean.toFixed(1) : 'null'}`);

      if (ePx === 0) {
        console.log('No valid pixels after processing.');
        console.log('C2');
        return;
      }
      if (eMean === null || !isFinite(eMean)) {
        console.log('Computation resulted in null/NaN.');
        console.log('C3');
        return;
      }
      answerVal = eMean;
      usedDataset = 'ERA5';
    }

    // 4. Validation & Final Answer
    const meets = answerVal >= threshMM;
    console.log(`Used: ${usedDataset}, Threshold 60 mm met?: ${meets ? 'Yes' : 'No'}`);
    if (!isFinite(answerVal)) {
      console.log('C3');
      return;
    }
    console.log(meets ? 'A' : 'B');
  } catch (err) {
    const msg = (err && err.message) ? err.message : String(err);
    console.log(`Error: ${msg.substring(0, 140)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
